class Widget {
public:
  Widget(int i, bool b);      // #1: Regular constructor
  Widget(int i, double d);    // #2: Another regular constructor

  // #3: Overload that hijacks braced initializations
  Widget(std::initializer_list<long double> il); 
};

// Parentheses trigger standard overload resolution
Widget w1(10, true);  // Calls #1
Widget w2(10, 5.0);   // Calls #2

// Braces strongly prefer the initializer_list overload
Widget w3{10, true};  // Calls #3 (10 and true are converted to long double)
Widget w4{10, 5.0};   // Calls #3 (10 and 5.0 are converted to long double)
